def strip(t):
    t=re.sub(r'--\[\[.*?\]\]','',t,flags=re.S)
    t=re.sub(r'\[\[.*?\]\]','""',t,flags=re.S)
    out=[]
    for l in t.split('\n'):
        l=re.sub(r'"(\\.|[^"\\])*"','""',l)
        l=re.sub(r"'(\\.|[^'\\])*'","''",l)
        l=re.sub(r'--.*$','',l)
        out.append(l)
    return out
